coding_problems.schema_sql:
CREATE TABLE students (student_id INT PRIMARY KEY, student_name VARCHAR(40) NOT NULL);
CREATE TABLE courses (course_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL);
CREATE TABLE enrollments (student_id INT NOT NULL, course_id INT NOT NULL, score INT NULL CHECK(score BETWEEN 0 AND 100), PRIMARY KEY(student_id,course_id));
